function parseName(name) {
  if (typeof name !== 'string') {
    throw new ValidationError('name must be a string');
  }
  const trimmed = name.trim();
  if (trimmed === '') {
    throw new ValidationError('name must not be empty');
  }
  return trimmed;
}

function parseAge(age) {
  let value;
  if (typeof age === 'number') {
    value = age;
  } else if (typeof age === 'string' && /^\s*\d+\s*$/.test(age)) {
    value = Number(age);
  } else {
    throw new ValidationError('age must be a whole number or a numeric string');
  }
  if (!Number.isInteger(value) || value < 0 || value > 150) {
    throw new ValidationError('age must be a whole number from 0 to 150');
  }
  return value;
}

function createUser(input) {
  if (input === null || typeof input !== 'object') {
    throw new ValidationError('input must be an object');
  }
  return { name: parseName(input.name), age: parseAge(input.age) };
}

