const { createUser, ValidationError } = require('../users');

test('creates a user', () => {
  assert.deepStrictEqual(createUser({ name: 'Asha', age: 31 }), { name: 'Asha', age: 31 });
});

test('trims the name and accepts numeric-string ages as numbers', () => {
  assert.deepStrictEqual(createUser({ name: '  Asha ', age: '42' }), { name: 'Asha', age: 42 });
});

test('accepts the age bounds 0 and 150', () => {
  assert.strictEqual(createUser({ name: 'A', age: 0 }).age, 0);
  assert.strictEqual(createUser({ name: 'A', age: 150 }).age, 150);
});

test('rejects invalid input with ValidationError', () => {
  const bad = [
    null,
    undefined,
    {},
    { name: '', age: 1 },
    { name: '   ', age: 1 },
    { name: 42, age: 1 },
    { name: 'A', age: 151 },
    { name: 'A', age: -1 },
    { name: 'A', age: 3.5 },
    { name: 'A', age: '3.5' },
    { name: 'A', age: '' },
    { name: 'A', age: '12abc' },
    { name: 'A', age: NaN },
    { name: 'A', age: Infinity },
    { name: 'A', age: null },
  ];
  for (const input of bad) {
    assert.throws(() => createUser(input), ValidationError, JSON.stringify(input));
  }
});

